def completar(apps, schema_editor):
    """
    - el técnico: el que era `asignado_a` (un usuario) pasa a `tecnico_id` si
      ese usuario tiene ficha de técnico;
    - la descripción: estaba cifrada y el dashboard la muestra y la busca;
    - el nombre: el ticket guarda el del abonado tal como estaba ese día.
    """
    from cryptography.fernet import InvalidToken
    from apps.core.fields import get_fernet

    Ticket = apps.get_model('soporte', 'Ticket')
    Tecnico = apps.get_model('core', 'Tecnico')
    tecnico_de_usuario = dict(
        Tecnico.objects.filter(usuario__isnull=False).values_list('usuario_id', 'id')
    )
    for t in Ticket.objects.select_related('client'):
        cambios = {}
        if t.asignado_a_id and t.asignado_a_id in tecnico_de_usuario:
            cambios['tecnico_id'] = tecnico_de_usuario[t.asignado_a_id]
        if t.descripcion and t.descripcion.startswith('enc::'):
            try:
                cambios['descripcion'] = get_fernet().decrypt(t.descripcion[5:].encode()).decode()
            except (InvalidToken, ValueError):
                cambios['descripcion'] = None
        if not t.nombre and t.client_id:
            cambios['nombre'] = t.client.nombre
            cambios['identificacion'] = t.client.identificacion
            cambios['telefono'] = t.client.telefono
        if cambios:
            Ticket.objects.filter(pk=t.pk).update(**cambios)


